import React, { useEffect, useState } from 'react';
import { WifiOff, Wifi, RefreshCw, CloudOff } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Çevrimdışı PWA Modu Bandı & Sync Kuyruğu
 * İnternet bağlantısı kesildiğinde kullanıcıyı uyarır.
 * Offline yapılan işlemleri localStorage kuyruğuna yazar;
 * bağlantı geri geldiğinde otomatik veya manuel senkronize eder.
 */

const QUEUE_KEY = 'mfk_offline_queue';

function getQueue() {
  try { return JSON.parse(localStorage.getItem(QUEUE_KEY) || '[]'); }
  catch { return []; }
}

function saveQueue(q) {
  localStorage.setItem(QUEUE_KEY, JSON.stringify(q));
}

/**
 * Çevrimdışı moda girilen kaydı kuyruğa ekler (diğer bileşenler bu fonksiyonu import edebilir)
 */
export function enqueueOfflineAction(type, payload) {
  const q = getQueue();
  q.push({ id: Date.now(), type, payload, timestamp: new Date().toISOString() });
  saveQueue(q);
}

export default function OfflinePWABanner() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [queue, setQueue] = useState(getQueue());
  const [syncing, setSyncing] = useState(false);
  const [visible, setVisible] = useState(!navigator.onLine);

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      setVisible(true);
      const q = getQueue();
      if (q.length > 0) {
        toast('İnternet bağlantısı geri geldi! Çevrimdışı kayıtlar senkronize edilebilir.', {
          icon: '📶',
          duration: 5000,
        });
      } else {
        // Kısa süre göster sonra kapat
        setTimeout(() => setVisible(false), 4000);
      }
    };

    const handleOffline = () => {
      setIsOnline(false);
      setVisible(true);
      toast.error('İnternet bağlantısı kesildi. Çevrimdışı moddasınız — girişler kaydedilecek.', { duration: 6000 });
    };

    const handleStorageChange = () => setQueue(getQueue());

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    window.addEventListener('storage', handleStorageChange);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  const handleSync = async () => {
    const q = getQueue();
    if (q.length === 0) { toast('Senkronize edilecek kayıt yok.'); return; }
    setSyncing(true);
    try {
      // Gerçek API çağrıları buraya gelir; şimdilik simüle ediyoruz
      await new Promise(r => setTimeout(r, 1200));
      saveQueue([]);
      setQueue([]);
      toast.success(`${q.length} çevrimdışı kayıt başarıyla senkronize edildi!`);
      setVisible(false);
    } catch {
      toast.error('Senkronizasyon hatası. Tekrar deneyin.');
    } finally {
      setSyncing(false);
    }
  };

  const handleClear = () => {
    saveQueue([]);
    setQueue([]);
    toast('Çevrimdışı kuyruk temizlendi.', { icon: '🗑️' });
    setVisible(false);
  };

  if (!visible) return null;

  if (!isOnline) {
    return (
      <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 w-full max-w-sm mx-auto px-4">
        <div className="bg-gray-900 text-white rounded-2xl shadow-2xl p-3.5 flex items-center gap-3">
          <div className="p-2 bg-red-500/20 rounded-xl shrink-0">
            <CloudOff className="w-5 h-5 text-red-400" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-bold text-sm">Çevrimdışı Mod</p>
            <p className="text-[11px] text-gray-400">
              {queue.length > 0 ? `${queue.length} kayıt kuyrukta bekliyor` : 'İnternet bağlantısı yok'}
            </p>
          </div>
          <WifiOff className="w-4 h-4 text-red-400 shrink-0" />
        </div>
      </div>
    );
  }

  // Online ama kuyrukta kayıt var
  if (isOnline && queue.length > 0) {
    return (
      <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 w-full max-w-sm mx-auto px-4">
        <div className="bg-blue-900 text-white rounded-2xl shadow-2xl p-3.5 flex items-center gap-3">
          <div className="p-2 bg-blue-500/20 rounded-xl shrink-0">
            <Wifi className="w-5 h-5 text-blue-300" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-bold text-sm">Bağlantı Geri Geldi</p>
            <p className="text-[11px] text-blue-300">{queue.length} çevrimdışı kayıt senkronize edilebilir</p>
          </div>
          <div className="flex gap-1.5 shrink-0">
            <button
              onClick={handleSync}
              disabled={syncing}
              className="flex items-center gap-1 text-[11px] font-bold bg-blue-500 hover:bg-blue-400 px-2.5 py-1.5 rounded-lg transition disabled:opacity-50"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${syncing ? 'animate-spin' : ''}`} />
              {syncing ? 'Sync...' : 'Sync'}
            </button>
            <button onClick={handleClear} className="text-[10px] text-blue-400 hover:text-white px-2 py-1.5 rounded-lg transition">
              Sil
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Online, kuyruk boş, kısa onay banner
  return (
    <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 w-full max-w-sm mx-auto px-4">
      <div className="bg-emerald-800 text-white rounded-2xl shadow-xl p-3 flex items-center gap-3">
        <Wifi className="w-4 h-4 text-emerald-300 shrink-0" />
        <p className="text-sm font-semibold flex-1">Bağlantı geri geldi</p>
        <button onClick={() => setVisible(false)} className="text-emerald-400 hover:text-white text-lg font-bold px-2">×</button>
      </div>
    </div>
  );
}
