import React, { useState } from 'react';
import { Calculator, TrendingUp, TrendingDown, DollarSign, Wheat, Milk } from 'lucide-react';

/**
 * Çiftlik Karlılık Hesaplayıcısı — IOFC & TMR Maliyet Analizi
 * Income Over Feed Cost (IOFC): Süt geliri eksi yem maliyeti hesabı.
 * Çiftçiye sürü başına ve insan başına günlük, haftalık, aylık karlılığı gösterir.
 */

const DEFAULT_INPUTS = {
  milkPrice: 14.65,       // ₺/litre (USK referans)
  avgDailyMilk: 28,       // litre/hayvan/gün
  milkingCows: 50,        // sağmal inek sayısı
  dailyFeedCostPerCow: 95, // ₺/hayvan/gün (TMR)
  otherCostPerCow: 18,    // ₺/hayvan/gün (enerji, sağlık, işçilik)
  herdSize: 80,           // toplam sürü
};

export default function FarmProfitabilityWidget() {
  const [inputs, setInputs] = useState(DEFAULT_INPUTS);
  const [showDetail, setShowDetail] = useState(false);

  const set = (key, val) => setInputs(prev => ({ ...prev, [key]: parseFloat(val) || 0 }));

  // Günlük hesaplamalar
  const dailyMilkRevenue = inputs.avgDailyMilk * inputs.milkPrice * inputs.milkingCows;
  const dailyFeedCost = inputs.dailyFeedCostPerCow * inputs.milkingCows;
  const dailyOtherCost = inputs.otherCostPerCow * inputs.herdSize;
  const dailyIOFC = dailyMilkRevenue - dailyFeedCost;
  const dailyNet = dailyMilkRevenue - dailyFeedCost - dailyOtherCost;

  const monthlyNet = dailyNet * 30;
  const iofc_per_cow = dailyIOFC / (inputs.milkingCows || 1);
  const breakeven_milk = (inputs.dailyFeedCostPerCow + inputs.otherCostPerCow) / (inputs.milkPrice || 1);

  const isProfit = dailyNet > 0;
  const profitColor = isProfit ? 'text-emerald-700' : 'text-red-700';
  const profitBg = isProfit ? 'bg-emerald-50 border-emerald-200' : 'bg-red-50 border-red-200';

  const fmt = (n) => Math.round(n).toLocaleString('tr-TR');

  return (
    <div className="card shadow-sm border border-gray-100">
      {/* Başlık */}
      <div className="flex items-center justify-between mb-4 pb-2 border-b">
        <div className="flex items-center gap-2">
          <div className="p-2 bg-emerald-50 text-emerald-700 rounded-xl">
            <Calculator className="w-4 h-4" />
          </div>
          <div>
            <h3 className="font-bold text-gray-900 text-sm">Karlılık Hesaplayıcı (IOFC)</h3>
            <p className="text-[11px] text-gray-400">Süt geliri eksi yem maliyeti analizi</p>
          </div>
        </div>
        <button
          onClick={() => setShowDetail(!showDetail)}
          className="text-xs font-semibold text-gray-500 hover:text-gray-800"
        >
          {showDetail ? 'Kapat' : 'Parametreler ↓'}
        </button>
      </div>

      {/* Parametreler */}
      {showDetail && (
        <div className="grid grid-cols-2 gap-3 mb-4 p-3 bg-gray-50 rounded-xl border border-gray-200">
          {[
            { key: 'milkPrice', label: '₺ Süt Fiyatı (₺/L)', step: '0.01' },
            { key: 'avgDailyMilk', label: 'Ort. Günlük Süt (L/baş)', step: '0.5' },
            { key: 'milkingCows', label: 'Sağmal İnek Sayısı', step: '1' },
            { key: 'herdSize', label: 'Toplam Sürü', step: '1' },
            { key: 'dailyFeedCostPerCow', label: 'TMR Yem Maliyeti (₺/baş/gün)', step: '1' },
            { key: 'otherCostPerCow', label: 'Diğer Gider (₺/baş/gün)', step: '1' },
          ].map(({ key, label, step }) => (
            <div key={key}>
              <label className="block text-[10px] font-bold text-gray-600 mb-1">{label}</label>
              <input
                type="number"
                step={step}
                value={inputs[key]}
                onChange={e => set(key, e.target.value)}
                className="w-full text-xs border border-gray-200 rounded-lg px-2 py-1.5 focus:ring-1 focus:ring-emerald-400 outline-none"
              />
            </div>
          ))}
        </div>
      )}

      {/* KPI kartları */}
      <div className="grid grid-cols-2 gap-2 mb-4">
        <div className={`rounded-xl p-3 border-2 ${profitBg}`}>
          <div className="flex items-center gap-1.5 mb-1">
            {isProfit ? <TrendingUp className="w-3.5 h-3.5 text-emerald-600" /> : <TrendingDown className="w-3.5 h-3.5 text-red-600" />}
            <span className="text-[10px] font-bold text-gray-600 uppercase">Günlük Net</span>
          </div>
          <p className={`text-xl font-black ${profitColor}`}>{isProfit ? '+' : ''}{fmt(dailyNet)} ₺</p>
          <p className="text-[10px] text-gray-500 mt-0.5">{inputs.milkingCows} sağmal x {inputs.avgDailyMilk} L</p>
        </div>

        <div className="rounded-xl p-3 border-2 bg-blue-50 border-blue-200">
          <div className="flex items-center gap-1.5 mb-1">
            <DollarSign className="w-3.5 h-3.5 text-blue-600" />
            <span className="text-[10px] font-bold text-gray-600 uppercase">Aylık Net</span>
          </div>
          <p className={`text-xl font-black ${profitColor}`}>{isProfit ? '+' : ''}{fmt(monthlyNet)} ₺</p>
          <p className="text-[10px] text-gray-500 mt-0.5">30 günlük projeksiyon</p>
        </div>
      </div>

      {/* Detay metrikleri */}
      <div className="grid grid-cols-3 gap-1.5 text-center bg-gray-50/80 p-3 rounded-xl">
        <div>
          <div className="flex items-center justify-center gap-1 mb-0.5">
            <Milk className="w-3 h-3 text-blue-500" />
          </div>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Süt Geliri/Gün</p>
          <p className="text-xs font-black text-gray-800">{fmt(dailyMilkRevenue)} ₺</p>
        </div>
        <div>
          <div className="flex items-center justify-center gap-1 mb-0.5">
            <Wheat className="w-3 h-3 text-amber-500" />
          </div>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Yem Maliyeti</p>
          <p className="text-xs font-black text-gray-800">{fmt(dailyFeedCost)} ₺</p>
        </div>
        <div>
          <p className="text-[10px] text-gray-400 font-bold uppercase">IOFC/Baş</p>
          <p className={`text-xs font-black ${iofc_per_cow >= 0 ? 'text-emerald-700' : 'text-red-700'}`}>
            {iofc_per_cow >= 0 ? '+' : ''}{fmt(iofc_per_cow)} ₺
          </p>
        </div>
      </div>

      {/* Başabaş noktası */}
      <div className="mt-3 flex items-center justify-between text-xs px-2">
        <span className="text-gray-500">Başabaş süt miktarı (litre/baş/gün):</span>
        <span className="font-black text-amber-700">{breakeven_milk.toFixed(1)} L</span>
      </div>
    </div>
  );
}
